"""Independent markers for native outcome framing, not generated by the renderer."""
from __future__ import annotations
import re
from jarvis.runtime.natural_commands import LANGUAGES

MARKERS={
 'pause':('пауз','paus','paus','pause','pausa','pausa','pausa'),
 'already':('уже','already','bereits','déjà','ya ','già','já'),
 'play':('воспроизвед|продолж|игра','resum|play','wiedergabe|musik','repr|lecture|musique','reanud|reprodu','ripr|riprodu','retom|reprodu'),
 'stop':('останов','stop','stopp','arrêt','deten|detuv|parad','ferm|interr','parad|parou|parei|interr'),
 'next':('следующ|переключ','next|skip','näch','suivant','siguiente','successiv|prossim','próxim|seguinte'),
 'unknown':('подтверж|результат|загруз|выполня','confirm|progress|pending','bestät|läuft|lad','confirm|cours','confirm|curso','conferm|corso','confirm|curso'),
 'network':('сет|соедин|подключ','network|connect','netz|verbind','réseau|connex','red|conex','rete|conness|irraggiungibile|collegamento','rede|liga'),
 'search':('наш[её]л','found','gefunden','trouvé','encontrado','trovato','encontrado')}

def check_outcome(kind: str, text: str, code: str) -> bool:
    i=LANGUAGES.index(code)
    if not re.search(MARKERS[kind][i],text,re.I):return False
    if kind=='search':
        # Separate lookup result, never a "now playing" statement.
        wrong=('сейчас играет','now playing','gerade läuft','lecture en cours','reproduciendo ahora','in riproduzione','a tocar agora')
        return wrong[i] not in text.casefold() and 'NEO QA' in text
    return bool(text.strip())
